async function main(ctx) {
  const input = ctx.input;
  let postUrn = input.postUrn;
  let activityUrn;

  // Extract ID from postUrn and convert to activityUrn for API calls
  if (postUrn.startsWith('urn:li:ugcPost:')) {
    const id = postUrn.replace('urn:li:ugcPost:', '');
    activityUrn = `urn:li:activity:${id}`;
  } else if (postUrn.startsWith('urn:li:share:')) {
    const id = postUrn.replace('urn:li:share:', '');
    activityUrn = `urn:li:activity:${id}`;
  } else if (postUrn.startsWith('urn:li:activity:')) {
    activityUrn = postUrn;
  } else {
    throw new Error('postUrn must be in format urn:li:ugcPost:ID or urn:li:share:ID');
  }

  return {
    originalPostUrn: input.postUrn,
    activityUrn: activityUrn,
    actor: input.actor,
    action: input.action,
    text: input.text,
    commentId: input.commentId,
    needsActor: !input.actor
  };
}

async function main(ctx) {
